'use client';

/**
 * ESVA OCR Nameplate Tool Page
 * -----------------------------
 * Camera capture or image upload → OCR → detected parameters → calculator links.
 *
 * PART 1: State & hooks
 * PART 2: Image upload/capture
 * PART 3: Results display
 * PART 4: Main page component
 */

import { useState, useRef, useCallback, useEffect } from 'react';
import { readApiErrorMessage } from '@/lib/error-messages';
import { decodeNameplateResponse, nameplateInputIssue, nameplateCalculatorInputs, type NameplateReviewData, type NameplateField } from '@/lib/nameplate-review';
import { calculatorHref } from '@/lib/calculator-catalog';
import {
  Camera,
  Upload,
  Loader2,
  Zap,
  RefreshCw,
  ArrowRight,
  Edit3,
  Check,
  X,
  AlertCircle,
} from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { getFirstAvailableVisionKey } from '@/lib/vision-byok';

// ═══════════════════════════════════════════════════════════════════════════════
// PART 1 — Types & State
// ═══════════════════════════════════════════════════════════════════════════════

// Vision 키·모델 해석은 공유 모듈(@/lib/vision-byok)로 일원화 — 로컬 사본 제거(§2.4).

type NameplateResult = NameplateReviewData;

const CALC_LABELS: Record<string, string> = {
  'voltage-drop': '전압강하 계산',
  'cable-sizing': '케이블 사이즈 선정',
  'breaker-sizing': '차단기 선정',
  'starting-current': '모터 기동전류',
  'motor-capacity': '전동기 용량 계산',
  'demand-diversity': '수용률 계산',
  'max-demand': '부하 계산',
  'transformer-capacity': '변압기 용량',
  'short-circuit': '단락전류 계산',
  'three-phase-power': '3상 전력 계산',
  'reactive-power': '역률 보상',
};

const PARAM_LABELS: Record<string, string> = {
  manufacturer: '제조사',
  model: '모델명',
  voltage: '전압',
  current: '전류',
  power: '전력',
  frequency: '주파수',
  serialNumber: '시리얼번호',
  phase: '상수',
  rating: '정격',
  efficiency: '효율',
  powerFactor: '역률',
  rpm: '회전속도',
  insulation: '절연등급',
  protection: '보호등급',
};

// ═══════════════════════════════════════════════════════════════════════════════
// PART 2 — Image Handling
// ═══════════════════════════════════════════════════════════════════════════════

function ImageUploader({
  onImageSelect,
  preview,
  onReset,
}: {
  onImageSelect: (file: File) => void;
  preview: string | null;
  onReset: () => void;
}) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  return (
    <div className="space-y-4">
      {preview ? (
        <div className="relative">
          <Image
            src={preview}
            alt="명판 이미지"
            width={1200}
            height={800}
            unoptimized
            className="w-full rounded-xl border border-[var(--border-default)] object-contain"
            style={{ maxHeight: 400 }}
          />
          <button
            type="button"
            aria-label="명판 이미지 삭제"
            onClick={onReset}
            className="absolute right-2 top-2 rounded-full bg-black/60 p-1.5 text-white hover:bg-black/80"
          >
            <X size={16} />
          </button>
        </div>
      ) : (
        <div className="flex flex-col gap-3 sm:flex-row">
          {/* Camera capture */}
          <button
            onClick={() => cameraInputRef.current?.click()}
            className="flex flex-1 items-center justify-center gap-2 rounded-xl border-2 border-dashed border-[var(--border-default)] bg-[var(--bg-secondary)] px-6 py-12 text-sm font-medium text-[var(--text-secondary)] transition-colors hover:border-[var(--color-primary)] hover:text-[var(--color-primary)]"
          >
            <Camera size={24} />
            카메라 촬영
          </button>
          <input
            ref={cameraInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            className="hidden"
            onChange={e => {
              const file = e.target.files?.[0];
              if (file) onImageSelect(file);
              // 같은 파일 재선택 시에도 onChange 가 다시 발화하도록 초기화 (bug L1)
              e.target.value = '';
            }}
          />

          {/* File upload */}
          <button
            onClick={() => fileInputRef.current?.click()}
            className="flex flex-1 items-center justify-center gap-2 rounded-xl border-2 border-dashed border-[var(--border-default)] bg-[var(--bg-secondary)] px-6 py-12 text-sm font-medium text-[var(--text-secondary)] transition-colors hover:border-[var(--color-primary)] hover:text-[var(--color-primary)]"
          >
            <Upload size={24} />
            이미지 업로드
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/png,image/webp"
            className="hidden"
            onChange={e => {
              const file = e.target.files?.[0];
              if (file) onImageSelect(file);
              // 같은 파일 재선택 시에도 onChange 가 다시 발화하도록 초기화 (bug L1)
              e.target.value = '';
            }}
          />
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// PART 3 — Results Display
// ═══════════════════════════════════════════════════════════════════════════════

function ParameterRow({
  label,
  value,
  onEdit,
}: {
  label: string;
  value: string;
  onEdit: (newValue: string) => void;
}) {
  const [editing, setEditing] = useState(false);
  const [editValue, setEditValue] = useState(value);

  if (editing) {
    return (
      <div className="flex items-center gap-2">
        <span className="w-24 shrink-0 text-xs font-medium text-[var(--text-tertiary)]">
          {label}
        </span>
        <input
          type="text"
          aria-label={`${label} 수정값`}
          maxLength={1000}
          value={editValue}
          onChange={e => setEditValue(e.target.value)}
          className="min-w-0 flex-1 rounded-md border border-[var(--border-default)] bg-[var(--bg-primary)] px-2 py-1 text-sm"
          autoFocus
        />
        <button
          type="button"
          aria-label={`${label} 수정 저장`}
          onClick={() => {
            onEdit(editValue);
            setEditing(false);
          }}
          className="min-h-11 min-w-11 rounded p-1 text-green-600 hover:bg-green-50"
        >
          <Check size={14} />
        </button>
        <button
          type="button"
          aria-label={`${label} 수정 취소`}
          onClick={() => {
            setEditValue(value);
            setEditing(false);
          }}
          className="min-h-11 min-w-11 rounded p-1 text-red-500 hover:bg-red-50"
        >
          <X size={14} />
        </button>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <span className="w-24 shrink-0 text-xs font-medium text-[var(--text-tertiary)]">
        {label}
      </span>
      <span className="min-w-0 flex-1 break-words text-sm font-medium text-[var(--text-primary)]">
        {value || '미기재/미판독'}
      </span>
      <button
        type="button"
        aria-label={`${label} 수정`}
        onClick={() => { setEditValue(value); setEditing(true); }}
        className="min-h-11 min-w-11 rounded p-1 text-[var(--text-tertiary)] hover:bg-[var(--bg-secondary)] hover:text-[var(--text-primary)]"
      >
        <Edit3 size={12} />
      </button>
    </div>
  );
}

function OCRResults({
  result,
  suggestedCalcs,
  onParamEdit, original, editedFields,
}: {
  result: NameplateResult;
  suggestedCalcs: string[];
  onParamEdit: (key: string, value: string) => void;
  original: NameplateResult; editedFields: string[];
}) {
  const params = Object.entries(PARAM_LABELS)
    .filter(([key]) => result[key as keyof NameplateResult])
    .map(([key, label]) => ({
      key,
      label,
      value: String(result[key as keyof NameplateResult]),
    }));

  return (
    <div className="space-y-6">
      {/*
        모델이 자기 확신도를 안 적어 보내면 값이 0 으로 떨어진다. 그걸 그대로
        "인식 정확도 0%" 로 쓰면 **다 읽어 놓고 실패한 것처럼 보인다** —
        라이브 실측(2026-07-29, Trafo-Union 명판)에서 제조사·형식·전압·전류·
        용량·주파수를 전부 옳게 읽고도 0% 였다. 없는 값을 0 으로 읽지 않는다.
      */}
      {result.confidence > 0 ? (
        <div className="flex items-center gap-3">
          <div className="h-2 flex-1 overflow-hidden rounded-full bg-[var(--bg-tertiary)]">
            <div
              className="h-full rounded-full bg-[var(--color-primary)] transition-all"
              style={{ width: `${Math.round(result.confidence * 100)}%` }}
            />
          </div>
          <span className="text-xs font-medium text-[var(--text-secondary)]">
            모델 추정 확신도 {Math.round(result.confidence * 100)}% (정답률 아님)
          </span>
        </div>
      ) : (
        <p
          data-testid="confidence-unreported"
          className="text-xs text-[var(--text-secondary)]"
        >
          모델이 확신도를 보고하지 않았습니다 — 아래 값은 원문과 대조해 확인하십시오.
        </p>
      )}

      {/* Parameters */}
      <div className="rounded-xl border border-[var(--border-default)] bg-[var(--bg-primary)] p-4">
        <h3 className="mb-3 text-sm font-semibold text-[var(--text-primary)]">
          인식된 파라미터
        </h3>
        <div className="space-y-2.5">
          {params.length > 0 ? (
            params.map(({ key, label, value }) => (
              <div key={key} className="rounded-lg border border-[var(--border-default)] p-3">
                <ParameterRow label={label} value={value} onEdit={newVal => onParamEdit(key, newVal)} />
                <p className="mt-1 text-xs text-[var(--text-secondary)]">{editedFields.includes(key) ? `사람 수정 · 최초 판독: ${original[key as NameplateField] ?? '미판독'}` : 'AI 추출 후보 · 원본 확인 필요'}</p>
                {nameplateInputIssue(key as NameplateField, value) && <p className="mt-1 text-xs text-[var(--text-secondary)]">{nameplateInputIssue(key as NameplateField, value)}</p>}
              </div>
            ))
          ) : (
            <p className="text-sm text-[var(--text-tertiary)]">
              인식된 파라미터가 없습니다. 이미지를 다시 촬영해 주세요.
            </p>
          )}
        </div>
      </div>

      <details className="rounded-xl border border-[var(--border-default)] p-4">
        <summary className="min-h-11 cursor-pointer text-sm font-semibold">미기재·미판독 항목 보완</summary>
        <p className="mb-3 text-xs text-[var(--text-secondary)]">값이 없는 항목은 0이 아닙니다. 원본에서 확인한 경우에만 입력하세요.</p>
        <div className="space-y-3">{Object.entries(PARAM_LABELS).filter(([key]) => !result[key as NameplateField]).map(([key, label]) =>
          <ParameterRow key={key} label={label} value="" onEdit={(value) => onParamEdit(key, value)} />)}</div>
      </details>
      <button type="button" className="min-h-11 rounded-lg border px-4 text-sm" onClick={() => {
        const url = URL.createObjectURL(new Blob([JSON.stringify({ schemaVersion: 1, source: 'nameplate-review', original,
          reviewed: result, editedFields, scope: 'This image only; not model training or a verified golden label.' }, null, 2)], { type: 'application/json' }));
        const link = document.createElement('a'); link.href = url; link.download = 'esa-nameplate-review.json'; link.click();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }}>원본·수정값 JSON 내보내기</button>
      {/* Raw text */}
      {result.rawText && (
        <details className="rounded-xl border border-[var(--border-default)]">
          <summary className="cursor-pointer px-4 py-3 text-xs font-medium text-[var(--text-secondary)]">
            원본 OCR 텍스트
          </summary>
          <pre className="whitespace-pre-wrap border-t border-[var(--border-default)] px-4 py-3 text-xs text-[var(--text-tertiary)]">
            {result.rawText}
          </pre>
        </details>
      )}

      {/* Suggested calculators */}
      {suggestedCalcs.length > 0 && (
        <div className="rounded-xl border border-[var(--border-default)] bg-[var(--bg-primary)] p-4">
          <h3 className="mb-3 text-sm font-semibold text-[var(--text-primary)]">
            확인 가능한 값으로 계산기 열기
          </h3>
          <p className="mb-3 text-xs text-[var(--text-secondary)]">복수 전압·범위·kA·kVA 등 의미가 다른 값은 자동 입력에서 제외합니다. 계산기에서 원본·단위·필수 입력을 확인하세요.</p>
          <div className="flex flex-wrap gap-2">
            {suggestedCalcs.map(calcId => (
              <Link
                key={calcId}
                href={calculatorHref(calcId, buildCalcParams(result, calcId))}
                className="inline-flex items-center gap-1.5 rounded-lg border border-[var(--color-primary)] bg-[var(--color-primary)]/5 px-3 py-2 text-xs font-medium text-[var(--color-primary)] transition-colors hover:bg-[var(--color-primary)] hover:text-white"
              >
                <Zap size={12} />
                {CALC_LABELS[calcId] ?? calcId}
                <ArrowRight size={12} />
              </Link>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/** 명판에서 읽은 값 — 계산기 폼을 미리 채운다. 빈 값은 calculatorHref 가 뺀다. */
function buildCalcParams(result: NameplateResult, calcId: string): Record<string, unknown> {
  return nameplateCalculatorInputs(result, calcId);
}

